class Solution {
public:
    string makeAntiPalindrome(string s) {
        int n = s.size();
        vector<int> cnt(26, 0);
        for (char c : s) if (++cnt[c - 'a'] > n / 2) return "-1";
        sort(s.begin(), s.end());
        int m = n / 2;
        if (s[m] != s[m - 1]) return s;
        int i = m;
        while (i < n && s[i] == s[m]) i++;
        int j = m;
        while (j < n && s[j] == s[n - 1 - j]) {
            if (i >= n) return "-1";
            swap(s[i], s[j]);
            i++;
            j++;
        }
        return s;
    }
};

class Solution {
    public String makeAntiPalindrome(String s) {
        int n = s.length();
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) {
            if (++cnt[c - 'a'] > n / 2) return "-1";
        }
        char[] cs = s.toCharArray();
        Arrays.sort(cs);
        int m = n / 2;
        if (cs[m] != cs[m - 1]) return new String(cs);
        int i = m;
        while (i < n && cs[i] == cs[m]) i++;
        int j = m;
        while (j < n && cs[j] == cs[n - 1 - j]) {
            if (i >= n) return "-1";
            char tmp = cs[i];
            cs[i] = cs[j];
            cs[j] = tmp;
            i++;
            j++;
        }
        return new String(cs);
    }
}

var makeAntiPalindrome = function(s) {
    const n = s.length;
    const cnt = new Array(26).fill(0);
    for (const c of s) {
        const idx = c.charCodeAt(0) - 97;
        if (++cnt[idx] > Math.floor(n / 2)) return '-1';
    }
    const cs = s.split('').sort();
    const m = Math.floor(n / 2);
    if (cs[m] !== cs[m - 1]) return cs.join('');
    let i = m;
    while (i < n && cs[i] === cs[m]) i++;
    let j = m;
    while (j < n && cs[j] === cs[n - 1 - j]) {
        if (i >= n) return '-1';
        const tmp = cs[i];
        cs[i] = cs[j];
        cs[j] = tmp;
        i++;
        j++;
    }
    return cs.join('');
};
